from lib import *
S = SS('e3')
steps = [
    step("MessagePack 的编码规则:0–127 的整数 1 字节(00、7f),128–255 变成 2 字节(cc 80),256–65535 是 3 字节(cd 01 00),65536 起 5 字节,2^32 起 9 字节;-1 到 -32 也是 1 字节;浮点一律 9 字节(cb 加 8 字节);字符串 31 字节以内头 1 字节(bf),32–255 字节头 2 字节(d9 20),256 字节起头 3 字节(da 01 00);bytes 头 2 字节(c4 03);{\"a\":1} 4 字节(81 a1 61 01),[1,2,3] 4 字节。JSON 里 127 是 3 字节、65536 是 5 字节、{\"a\":1} 是 7 字节、0.1 是 3 字节——短的浮点在 JSON 里反而比 9 字节短。", t=tl(S(1)), done=lidx(S(1), '{"a":1}'), mark=lidx(S(1), '浮点 0.1'), b=bars([['整数 127', 1, '1'], ['整数 128', 2, '2'], ['整数 65536', 5, '5'], ['浮点 0.1', 9, '9'], ['{"a":1}', 4, '4']], 10, done=[0, 1, 2, 4], mark=[3]), kv=KV([['小整数', '1 字节;随数值变大 2/3/5/9 字节'], ['字符串头', '31 以内 1 字节,之后 2、3 字节'], ['浮点', '一律 9 字节(JSON 里 0.1 只要 3 字节)']], ['浮点'])),
    step("四个数据集的体积(整批作为一个数组,紧凑 JSON 对 MessagePack):products 7214163 → 6357308 字节,省下 11.9%;timeseries 2744543 → 2000003,省下 27.1%;nested 5582052 → 4062921,省下 27.2%;blobby(JSON 里的二进制要 base64)2224945 → 1652673,省下 25.7%。zstd-3 压缩之后:products JSON 1331144、MessagePack 1413136(MessagePack 大 6.2%);timeseries 352531 对 298689(小 15.3%);nested 660737 对 606310(小 8.2%);blobby 1578156 对 1579529(基本相同,随机二进制压不动)。gzip-6、lz4 上 products 也是 MessagePack 略大。", t=tl(S(2)), done=lidx(S(2), 'timeseries'), mark=lidx(S(2), 'products'), b=bars([['products 压缩后:JSON', 1331144, '1331144'], ['products 压缩后:MsgPack', 1413136, '1413136'], ['timeseries 压缩后:JSON', 352531, '352531'], ['timeseries 压缩后:MsgPack', 298689, '298689']], 1420000, mark=[1], done=[3]), kv=KV([['未压缩', 'MessagePack 小 11.9%–27.2%'], ['zstd-3 压缩后 products', 'MessagePack 反而大 6.2%'], ['zstd-3 压缩后 timeseries', 'MessagePack 小 15.3%']], ['zstd-3 压缩后 products'])),
    step("MessagePack 的字节按类型拆开。products:字符串 64.8%、键名 25.5%、浮点 5.7%、整数 3.1%、容器头 0.9%;timeseries:键名 57.5%、浮点 22.5%、整数 17.5%、容器头 2.5%。products 省的字节少(11.9%)是因为大头是字符串,而字符串在 MessagePack 里和 JSON 差不多大;timeseries 省得多(27.1%)是因为字段名短但每条重复、数值也有整数可以变短。数字多的数据受益大,字符串多的数据受益小。", t=tl(S(3)), done=lidx(S(3), 'timeseries:MessagePack'), mark=lidx(S(3), 'products:MessagePack'), b=bars([['products 字符串 %', 64.8, '64.8'], ['products 键名 %', 25.5, '25.5'], ['timeseries 键名 %', 57.5, '57.5'], ['timeseries 浮点 %', 22.5, '22.5']], 66, mark=[0], done=[2]), kv=KV([['products', '字符串 64.8%,省 11.9%'], ['timeseries', '键名 57.5%,省 27.1%'], ['结论', '数值多的数据受益大']], ['结论'])),
    step("速度(各取 7 次中位数):products,json.dumps 40.8 ms、orjson.dumps 5.0 ms、msgpack.packb 13.7 ms;json.loads 45.0 ms、orjson.loads 21.7 ms、msgpack.unpackb 32.9 ms。timeseries,dumps 25.2/3.3/8.7 ms,loads 25.4/10.5/16.3 ms。msgpack 比标准库 json 快(打包约 3 倍、解包约 1.4–1.6 倍),但比 orjson 慢。“二进制格式一定比 JSON 快”不成立——要看对比的是哪个 JSON 实现。", t=tl(S(4)), done=lidx(S(4), 'products:json.dumps'), mark=lidx(S(4), 'timeseries:json.dumps'), b=bars([['json.dumps ms', 40.8, '40.8'], ['orjson.dumps ms', 5.0, '5.0'], ['msgpack.packb ms', 13.7, '13.7'], ['msgpack.unpackb ms', 32.9, '32.9'], ['orjson.loads ms', 21.7, '21.7']], 46, done=[1], mark=[0]), kv=KV([['dumps(products)', 'orjson 5.0 < msgpack 13.7 < json 40.8 ms'], ['loads(products)', 'orjson 21.7 < msgpack 32.9 < json 45.0 ms'], ['结论', '要看对比的是哪个 JSON 实现']], ['结论'])),
    step("类型保真:tuple (1,2) 打包再解出来是列表 [1, 2];整数键 {1:'a'} 能打包,但默认 strict_map_key=True 解包时抛 ValueError,要传 strict_map_key=False 才还原;bytes 和 str 用 use_bin_type=True 分得开,用旧格式(use_bin_type=False)bytes 和 str 解出来都是 str;2^63 能编码(9 字节),2^64 抛 OverflowError;nan 能往返;datetime 和 set 抛 TypeError。比 JSON 多出 bytes 和整数键,但仍然没有日期和集合。", t=tl(S(5)), done=lidx(S(5), '整数键'), mark=lidx(S(5), 'use_bin_type=False'), b=bars([['tuple 往返后变成 list', 1, '变了'], ['bytes/str 区分(use_bin_type=True)', 1, '保留'], ['2^64', 0, 'OverflowError']], 1.2, done=[1], mark=[0, 2]), kv=KV([['tuple', '解出来是 list'], ['整数键', '解包要 strict_map_key=False'], ['2^64', 'OverflowError']], ['整数键'])),
    step("流式:2000 条记录拼成一个没有分隔符的 MessagePack 流(637751 字节),按 1000 字节切成 638 块喂给 Unpacker,取出 2000/2000 条;JSON Lines 是 723399 字节,靠换行分隔。流被截断在中间时,Unpacker 取出 1001 条完整记录,最后半条不报错、留在缓冲里;JSON Lines 同样位置截断,按行解析 1001/1002 行可解析,最后半行 json.loads 抛 JSONDecodeError。MessagePack 的每个值自带长度,不需要分隔符,但半条记录要靠 Unpacker 自己判断。", t=tl(S(6)), done=lidx(S(6), 'MessagePack 流'), mark=lidx(S(6), '把流截断'), b=bars([['MessagePack 流取出', 2000, '2000'], ['截断后取出完整记录', 1001, '1001']], 2100, done=[0], mark=[1]), kv=KV([['MessagePack 流', '637751 字节,2000 条全取出'], ['JSON Lines', '723399 字节,靠换行分隔'], ['被截断的最后半条', 'Unpacker 不报错,留在缓冲里']], ['被截断的最后半条'])),
    step("products 上 MessagePack 压缩后反而更大,检验两个猜想。猜想 1(浮点的 8 字节二进制接近随机):把 price、rating 改成整数后差距从 +6.2% 变成 +3.9%,去掉这两个字段后仍然 +5.9%,猜想 1 不是主因;1000 个 price 的 float64 二进制 zstd 后 3732 字节,同样的文本 2619 字节,浮点确实压得差些。猜想 2(长度前缀):只看 title 字段(2 万个长短不一的字符串)单独压缩,JSON 数组 413803、MessagePack 数组 436587(大 5.5%)、换行分隔的纯文本 409620;url 长度几乎一样,三者基本相同(11989、12386、12331)。长度前缀是一个每条都要单独存储的数字,而 JSON 的结束引号更容易被预测——这是我对这个差别的解释,没有拆到熵编码内部去验证。", t=tl(S(7)), done=lidx(S(7), 'title'), mark=lidx(S(7), '去掉 price 和 rating'), b=bars([['title:JSON 数组 zstd', 413803, '413803'], ['title:MsgPack 数组 zstd', 436587, '436587'], ['title:纯文本 zstd', 409620, '409620'], ['url:MsgPack 数组 zstd', 12386, '12386']], 440000, mark=[1], done=[0, 2]), kv=KV([['去掉浮点字段后', 'MessagePack 仍大 5.9%'], ['title(长度不一)', 'MessagePack 大 5.5%'], ['url(长度一致)', '三者基本相同']], ['title(长度不一)'])),
]
A = mkarte('e3', 3, '编码,MessagePack,JSON,压缩,orjson,字节构成,Python,真实验证,动画演示',
    '实测 MessagePack 对 JSON:未压缩小 11.9%–27.2%,但 products(字符串多)用 zstd 压缩后 MessagePack 反而大 6.2%,数值多的 timeseries 小 15.3%;速度比标准库 json 快、比 orjson 慢;整数键、bytes 能保留,tuple 变 list,2^64 溢出。',
    'MessagePack 常被说成“更小更快的 JSON”。这篇用 4 个数据集量一量:未压缩和压缩之后各小多少,为什么有的数据几乎没变小,速度比谁快,类型保真和流式读取有什么不同。',
    [('11.9% 对 27.1%', '未压缩时 MessagePack 比 JSON 小的比例:字符串多的 products 与数值多的 timeseries'), ('+6.2%', 'products 用 zstd-3 压缩后,MessagePack 比 JSON 反而大的比例'), ('13.7 对 5.0 ms', 'products 打包:msgpack 与 orjson 的耗时(标准库 json 是 40.8 ms)')],
    [('编码规则', '<p>小整数 1 字节,更大的整数 2、3、5、9 字节;字符串头 1 到 3 字节;浮点一律 9 字节;容器头 1 字节起。JSON 里短的浮点(0.1 只要 3 字节)和 {\"a\":1}(7 字节)对比 MessagePack 的 9 字节和 4 字节,小整数、短键名占优的是 MessagePack,短浮点占优的是 JSON。</p>'),
     ('四个数据集', '<p>未压缩时 MessagePack 小 11.9%(products)到 27.2%(nested)。但 zstd 压缩之后差距变了:products 上 MessagePack 反而大 6.2%,timeseries 小 15.3%,nested 小 8.2%,含随机二进制的 blobby 基本相同。</p>'),
     ('为什么差别这么大', '<p>字符串多的数据(products 字符串占 64.8%),MessagePack 没什么可省;数值多的数据(timeseries 键名 57.5%、浮点和整数共 40%)省得多。数字越多,受益越大。</p>'),
     ('速度', '<p>msgpack 比标准库 json 快(打包约 3 倍),但比 orjson 慢。“二进制就是快”不成立,要看对比的是哪个 JSON 实现。</p>'),
     ('类型', '<p>MessagePack 比 JSON 多了 bytes 和整数键(解包要 strict_map_key=False),tuple 会变成 list,2^64 溢出,datetime 和 set 要自己处理。bytes 和 str 的区分需要 use_bin_type=True。</p>'),
     ('流式读取', '<p>每个 MessagePack 值自带长度,多条记录直接拼接,用 Unpacker 分块喂入就能取出(实验里 2000/2000)。JSON Lines 靠换行分隔。被截断的最后半条,Unpacker 不报错,只是还不能取出。</p>'),
     ('为什么压缩后反而更大', '<p>检验了两个猜想:浮点的 8 字节二进制压得差一些,但去掉浮点字段后 MessagePack 仍然大 5.9%,所以不是主因;长度不一的 title 字符串单独压缩时,MessagePack 数组比 JSON 数组大 5.5%,长度一致的 url 就没有差别。我的解释是字符串长度前缀是每条都要单独存的信息,而 JSON 的结束引号更好预测,这个解释没有拆到压缩器内部验证。</p>')],
    steps,
    [ENV_E + '。msgpack 1.2.3、orjson 3.13.0 临时安装;数据集见第 1 篇;体积和类型是确定性结果,速度是 7 次中位数;第七节的字段单独压缩用 zstd 级别 3',
     '没有验证:CBOR、BSON 等其它二进制 JSON;MessagePack 的扩展类型(时间戳等);用 msgpack-numpy 之类处理数组;不同 zstd 级别下 products 的差距会不会变;为什么长度前缀更难压缩的压缩器内部原因(只在字段级别验证了现象);Python 以外的 MessagePack 实现'],
    'MessagePack')
